(581020, 60223, 16266, '<td valign="top">yeah, cleverly done... i think the ace adds interest, and also cleverly covers up the  colors on the jack.  nice job.</td>', 'yeah, cleverly done... i think the ace adds interest, and also cleverly covers up the  colors on the jack.  nice job.', '2004-02-16 00:12:55.000000', NULL, 1),
