(581466, 60082, 6008, '<td valign="top">I like the harsh mood from the black, stripped bark. The seeming mist in the background adds a nice layer to it too. I dont normally complain about borders, but this one seems to invade the picture too much, it''s almost like it''s in the way of me seeing more of the limbs.</td>', 'I like the harsh mood from the black, stripped bark. The seeming mist in the background adds a nice layer to it too. I dont normally complain about borders, but this one seems to invade the picture too much, it''s almost like it''s in the way of me seeing more of the limbs.', '2004-02-16 08:20:01.000000', NULL, 1),
(581467, 60394, 11693, '<td valign="top">Well done.  Your black is rich and contains details. 7</td>', 'Well done.  Your black is rich and contains details. 7', '2004-02-16 08:20:05.000000', NULL, 1),
(581469, 60161, 6008, '<td valign="top">I like the hair over the eyelid, and the catchlight on the eye is good. Only negative is the vast amount of negative black space on the right.</td>', 'I like the hair over the eyelid, and the catchlight on the eye is good. Only negative is the vast amount of negative black space on the right.', '2004-02-16 08:24:06.000000', NULL, 1),
(581471, 60577, 11693, '<td valign="top">Great photo, I just does not have a high "black" value. 5</td>', 'Great photo, I just does not have a high "black" value. 5', '2004-02-16 08:24:50.000000', NULL, 1),
(581472, 60660, 11693, '<td valign="top">Realy captures the texture and richness that is black.  Good details and DOF. 7</td>', 'Realy captures the texture and richness that is black.  Good details and DOF. 7', '2004-02-16 08:25:33.000000', NULL, 1),
(581476, 60475, 6008, '<td valign="top">Black is really hard to exposure. You have the wisps on the ''outer'' part of the cat, and certainly the eyes, but the details of the fur and his/her face is mostly lost. There is some, but not significantly enough to break up the mass of black.</td>', 'Black is really hard to exposure. You have the wisps on the ''outer'' part of the cat, and certainly the eyes, but the details of the fur and his/her face is mostly lost. There is some, but not significantly enough to break up the mass of black.', '2004-02-16 08:30:00.000000', NULL, 1),
(581478, 60698, 6008, '<td valign="top">Not really a fan of the placement, other than the top it is surrounded by a lot of negative black space. I think a tighter crop would have helped and also brought more attention to the detail of the helmet. It also looks like it may have been too close to the backdrop as the black has some texture along the beam of light. The helmet itself is interesting - it has a distinct futuristic feel to it. The lighting is good with no bad reflections or bright spots.</td>', 'Not really a fan of the placement, other than the top it is surrounded by a lot of negative black space. I think a tighter crop would have helped and also brought more attention to the detail of the helmet. It also looks like it may have been too close to the backdrop as the black has some texture along the beam of light. The helmet itself is interesting - it has a distinct futuristic feel to it. The lighting is good with no bad reflections or bright spots.', '2004-02-16 08:34:22.000000', NULL, 1),
(581479, 60223, 11693, '<td valign="top">Good shot.  The balck is rich and the focus is great. My favorite shot so far. 8</td>', 'Good shot.  The balck is rich and the focus is great. My favorite shot so far. 8', '2004-02-16 08:34:33.000000', NULL, 1),
(581480, 60628, 6008, '<td valign="top">The texture of the leather is good, but the light is a little too harsh on some spots.</td>', 'The texture of the leather is good, but the light is a little too harsh on some spots.', '2004-02-16 08:36:47.000000', NULL, 1),
(581482, 60184, 6008, '<td valign="top">Flames are hard to photograph and you''ve done fairly well. The triangular top of the candle also adds interest. The flame here seems to be the focus point with the black candle part almost non-existent due to the background, which unfortunately is what a lot of voters are going to be judging on.</td>', 'Flames are hard to photograph and you''ve done fairly well. The triangular top of the candle also adds interest. The flame here seems to be the focus point with the black candle part almost non-existent due to the background, which unfortunately is what a lot of voters are going to be judging on.', '2004-02-16 08:40:54.000000', NULL, 1),
(581484, 60578, 15920, '<td valign="top">It isn''t a cat, and it isn''t that dark an image.  +10  Depth of field could have been a little deeper to get some more detail and interest in the fur.  -3  The specs of junk in the fur add a lot.  Net 8.</td>', 'It isn''t a cat, and it isn''t that dark an image.  +10  Depth of field could have been a little deeper to get some more detail and interest in the fur.  -3  The specs of junk in the fur add a lot.  Net 8.', '2004-02-16 08:43:49.000000', NULL, 1),
(581485, 60442, 6008, '<td valign="top">The floor looks dirty and old but in some ways that seems to add to the mood. I like the highligts on the side of whatever that is. It almost reminds me of kitchen hockey. It also seems like you thought about the placement of the item and the direction of the lines too.</td>', 'The floor looks dirty and old but in some ways that seems to add to the mood. I like the highligts on the side of whatever that is. It almost reminds me of kitchen hockey. It also seems like you thought about the placement of the item and the direction of the lines too.', '2004-02-16 08:45:41.000000', NULL, 1),
(581486, 60657, 6008, '<td valign="top">Not really my type of thing so I cant really judge it good or bad with any decree of knowledge or taste. It''s very abstract/impressionistic.</td>', 'Not really my type of thing so I cant really judge it good or bad with any decree of knowledge or taste. It''s very abstract/impressionistic.', '2004-02-16 08:49:39.000000', NULL, 1),
(581487, 60163, 6008, '<td valign="top">Good diagonal, excellent lighting, the texture in both the foreground item and the background compliment each other well. The chrone is well lit and shiny without losing any details. Would make a great advertising shot.</td>', 'Good diagonal, excellent lighting, the texture in both the foreground item and the background compliment each other well. The chrone is well lit and shiny without losing any details. Would make a great advertising shot.', '2004-02-16 08:51:51.000000', NULL, 1),
(581489, 60128, 6008, '<td valign="top">The texture and the lighting on the mittens are good, even some details in the fur at the top, but the background does not really compliment them well. It''s far too busy and almost taking away the focus from the mittens, and there is an uncovered spot on the top left. Something plain or with texture would likely have helped it a lot.</td>', 'The texture and the lighting on the mittens are good, even some details in the fur at the top, but the background does not really compliment them well. It''s far too busy and almost taking away the focus from the mittens, and there is an uncovered spot on the top left. Something plain or with texture would likely have helped it a lot.', '2004-02-16 08:54:38.000000', NULL, 1),
(581492, 60697, 6008, '<td valign="top">The lighting is good, it''s nicely sharp, but I really dislike the frame. Not sure if it''s a mirror frame or a filter frame but it distracts from the image quite a bit.</td>', 'The lighting is good, it''s nicely sharp, but I really dislike the frame. Not sure if it''s a mirror frame or a filter frame but it distracts from the image quite a bit.', '2004-02-16 08:59:04.000000', NULL, 1),
(581494, 60202, 6008, '<td valign="top">Good color in the left eye but they both seem a little dim. Black is hard to expose right, and the majority of the details of the fur/nose etc seems to be lost or not as strong as they probably should be.</td>', 'Good color in the left eye but they both seem a little dim. Black is hard to expose right, and the majority of the details of the fur/nose etc seems to be lost or not as strong as they probably should be.', '2004-02-16 09:00:57.000000', NULL, 1),
(581497, 60586, 6008, '<td valign="top">Interesting idea - the texture is good but the dof seems a little off with the focus on the middle ''hill''. Being oof has given the front ''hill'' more texture, but I think it may have just had a stronger impact if they were all in focus and had a uniform look with the lines and curves as the strong point.</td>', 'Interesting idea - the texture is good but the dof seems a little off with the focus on the middle ''hill''. Being oof has given the front ''hill'' more texture, but I think it may have just had a stronger impact if they were all in focus and had a uniform look with the lines and curves as the strong point.', '2004-02-16 09:04:47.000000', NULL, 1),
(581500, 60591, 6008, '<td valign="top">I like the halo over the hill and the trees framing the left side is interesting. The red ''planet''? certainly stands out amidst all the stars. A very peaceful image.</td>', 'I like the halo over the hill and the trees framing the left side is interesting. The red ''planet''? certainly stands out amidst all the stars. A very peaceful image.', '2004-02-16 09:06:48.000000', NULL, 1),
(581503, 60222, 6008, '<td valign="top">Texture is good, lighting is excellent, placement is good too. The white (I have no idea about flower parts) really stands out against the black. Good shot!</td>', 'Texture is good, lighting is excellent, placement is good too. The white (I have no idea about flower parts) really stands out against the black. Good shot!', '2004-02-16 09:08:15.000000', NULL, 1),
(581525, 60301, 10686, '<td valign="top">Wonderful lighting, might be better if the illuminated area were not as centered.</td>', 'Wonderful lighting, might be better if the illuminated area were not as centered.', '2004-02-16 09:30:38.000000', NULL, 1),
(581530, 60202, 10686, '<td valign="top">Very nice image, but I''d like to see the eyes pop out a bit more</td>', 'Very nice image, but I''d like to see the eyes pop out a bit more', '2004-02-16 09:33:42.000000', NULL, 1),
(581533, 60570, 10686, '<td valign="top">This is a good idea, but the subject is not sharp and the contrast is way too flat.</td>', 'This is a good idea, but the subject is not sharp and the contrast is way too flat.', '2004-02-16 09:36:04.000000', NULL, 1),
(581535, 60475, 10686, '<td valign="top">Love the way the eyes jump out. Very good!</td>', 'Love the way the eyes jump out. Very good!', '2004-02-16 09:36:56.000000', NULL, 1),
(581539, 60585, 14614, '<td valign="top">Excellent detail.  Like how it fills the frame.</td>', 'Excellent detail.  Like how it fills the frame.', '2004-02-16 09:37:43.000000', NULL, 1),
(581540, 60511, 10686, '<td valign="top">Interesting, but needs more tonal range, it''s too flat.</td>', 'Interesting, but needs more tonal range, it''s too flat.', '2004-02-16 09:38:02.000000', NULL, 1),
(581541, 60645, 10686, '<td valign="top">I like the idea, but the solarization or whatever effect was used here, kills it for me.</td>', 'I like the idea, but the solarization or whatever effect was used here, kills it for me.', '2004-02-16 09:39:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(581543, 60542, 14614, '<td valign="top">Nicely composed (would like the 4 buckels to be sharper focused since they stand out against the black)</td>', 'Nicely composed (would like the 4 buckels to be sharper focused since they stand out against the black)', '2004-02-16 09:39:33.000000', NULL, 1),
