(581559, 60665, 10686, '<td valign="top">Nice, but the green leafy garnish becomes the real subject, since it is the only spot of color.</td>', 'Nice, but the green leafy garnish becomes the real subject, since it is the only spot of color.', '2004-02-16 09:44:44.000000', NULL, 1),
(581560, 60539, 14614, '<td valign="top">Great timing, interesting composition, thick border works well.  young subject draws my eye through the frame. (hot spots are a little distracting) One of my favorites.</td>', 'Great timing, interesting composition, thick border works well.  young subject draws my eye through the frame. (hot spots are a little distracting) One of my favorites.', '2004-02-16 09:45:37.000000', NULL, 1),
(581562, 60599, 14614, '<td valign="top">Who''s down there?  Interesting angle and use of b&amp;w. (would like a bit sharper focus throughout) Cropped to a unique shape.</td>', 'Who''s down there?  Interesting angle and use of b&w. (would like a bit sharper focus throughout) Cropped to a unique shape.', '2004-02-16 09:46:52.000000', NULL, 1),
(581565, 60392, 14614, '<td valign="top">Clever title. Good use of b&amp;w, would like a bit more light in the lower center.  Overall interesting composition</td>', 'Clever title. Good use of b&w, would like a bit more light in the lower center.  Overall interesting composition', '2004-02-16 09:48:13.000000', NULL, 1),
(581566, 60603, 16900, '<td valign="top">This is a great photo, and should place top ten...Great work!!</td>', 'This is a great photo, and should place top ten...Great work!!', '2004-02-16 09:48:20.000000', NULL, 1),
(581569, 60624, 14614, '<td valign="top">Great texture, composition is pleasing, border works well.  One of my top picks</td>', 'Great texture, composition is pleasing, border works well.  One of my top picks', '2004-02-16 09:49:37.000000', NULL, 1),
(581572, 60463, 10686, '<td valign="top">nice, but I think it would look better in color to show the reflections.</td>', 'nice, but I think it would look better in color to show the reflections.', '2004-02-16 09:51:25.000000', NULL, 1),
(581582, 60238, 10686, '<td valign="top">pretty bird, but he''s out of focus, while the tree in the background is sharper.</td>', 'pretty bird, but he''s out of focus, while the tree in the background is sharper.', '2004-02-16 09:58:22.000000', NULL, 1),
(581599, 60370, 15920, '<td valign="top">So you are in on the challenge rules, and you might have taken the happiest picture in the contest.  The lighting is perfect, despite the difficulty of the baseball hat, everything is in focus, and the colors are great. - 10</td>', 'So you are in on the challenge rules, and you might have taken the happiest picture in the contest.  The lighting is perfect, despite the difficulty of the baseball hat, everything is in focus, and the colors are great. - 10', '2004-02-16 10:09:12.000000', NULL, 1),
(581602, 60525, 15920, '<td valign="top">Good composition, nice colors, but the focus could have been a little stronger</td>', 'Good composition, nice colors, but the focus could have been a little stronger', '2004-02-16 10:13:59.000000', NULL, 1),
(581603, 60536, 15920, '<td valign="top">You captured the idea of "angry young man" perfectly.</td>', 'You captured the idea of "angry young man" perfectly.', '2004-02-16 10:14:58.000000', NULL, 1),
