(582946, 60659, 245, '<td valign="top">All this says to me is ''bag''... maybe if it were filled with water to make the wrinkles smoother it would pop more. The composition is nice, it''s just the subject I find a bit uninteresting.</td>', 'All this says to me is ''bag''... maybe if it were filled with water to make the wrinkles smoother it would pop more. The composition is nice, it''s just the subject I find a bit uninteresting.', '2004-02-17 07:07:44.000000', NULL, 1),
(582947, 60542, 245, '<td valign="top">A nice, simple, sentimental picture! Very crisp, too.</td>', 'A nice, simple, sentimental picture! Very crisp, too.', '2004-02-17 07:08:50.000000', NULL, 1),
(582949, 60536, 245, '<td valign="top">I really like the lighting in this one! It''s very crisp, too, for what looks like a low-light situation. :)</td>', 'I really like the lighting in this one! It''s very crisp, too, for what looks like a low-light situation. :)', '2004-02-17 07:11:36.000000', NULL, 1),
(582950, 60182, 245, '<td valign="top">I like this a lot, it really sticks to the spirit of the chalenge. I just wish the back edges of the wings and tail were a little sharper, I don''t thik the image would suffer from sharpening much! :)</td>', 'I like this a lot, it really sticks to the spirit of the chalenge. I just wish the back edges of the wings and tail were a little sharper, I don''t thik the image would suffer from sharpening much! :)', '2004-02-17 07:13:40.000000', NULL, 1),
(582951, 60161, 245, '<td valign="top">I want to see more detail in the area around the eye!</td>', 'I want to see more detail in the area around the eye!', '2004-02-17 07:14:06.000000', NULL, 1),
(582954, 60183, 245, '<td valign="top">I would have tried to frame this a bit wider, the jaw is a bit close to the left edge for my tastes. Otherwise, a really cool picture! A little spot-editing on the eye to make the black a bit more even might look nice too.</td>', 'I would have tried to frame this a bit wider, the jaw is a bit close to the left edge for my tastes. Otherwise, a really cool picture! A little spot-editing on the eye to make the black a bit more even might look nice too.', '2004-02-17 07:16:19.000000', NULL, 1),
(582956, 60548, 245, '<td valign="top">Unless the cross itself was leaning, I''d prefer it if the cross were true vertical in the frame. I really like the colors you''ve captured, and the focus is gentle.</td>', 'Unless the cross itself was leaning, I''d prefer it if the cross were true vertical in the frame. I really like the colors you''ve captured, and the focus is gentle.', '2004-02-17 07:18:18.000000', NULL, 1),
(582957, 60675, 245, '<td valign="top">More black on top, less black on bottom! :)</td>', 'More black on top, less black on bottom! :)', '2004-02-17 07:19:00.000000', NULL, 1),
(582959, 60233, 245, '<td valign="top">I''d like the blow-outs of the white a lot more if the shadows didn''t look noisy, actual wall texture or not. :)</td>', 'I''d like the blow-outs of the white a lot more if the shadows didn''t look noisy, actual wall texture or not. :)', '2004-02-17 07:20:31.000000', NULL, 1),
(582960, 60186, 245, '<td valign="top">There''s a lot of nice color in the flower, but it''s muted and doesn''t overwhelm the blackness of this piture. :)</td>', 'There''s a lot of nice color in the flower, but it''s muted and doesn''t overwhelm the blackness of this piture. :)', '2004-02-17 07:21:23.000000', NULL, 1),
