(583262, 60506, 5391, '<td valign="top">Wow - very cool shot.  Love the use of space you''ve managed in the composition.  Very artistic.  Very sharp image while conveying motion.  I think this may, unfortunately, be underappreciated by the voting audience at DPC looking for a quick "wow".  I hope you get the high score you deserve.  10</td>', 'Wow - very cool shot.  Love the use of space you''ve managed in the composition.  Very artistic.  Very sharp image while conveying motion.  I think this may, unfortunately, be underappreciated by the voting audience at DPC looking for a quick "wow".  I hope you get the high score you deserve.  10', '2004-02-17 11:12:33.000000', NULL, 1),
(583271, 60548, 5391, '<td valign="top">I really like the monochrome fee that the greens create.  They compliment the black very nicely.  Very nice image.  7</td>', 'I really like the monochrome fee that the greens create.  They compliment the black very nicely.  Very nice image.  7', '2004-02-17 11:24:45.000000', NULL, 1),
(583275, 60628, 5391, '<td valign="top">Interesting textures and lighting - perhaps a bit too high contrast in a few areas - the blown out highlights are a distraction.  Otherwise, though, a nice image.  Especially love the background which tends to reflect the same lighting in a subtle manner that brings your eye back to the subject.</td>', 'Interesting textures and lighting - perhaps a bit too high contrast in a few areas - the blown out highlights are a distraction.  Otherwise, though, a nice image.  Especially love the background which tends to reflect the same lighting in a subtle manner that brings your eye back to the subject.', '2004-02-17 11:28:58.000000', NULL, 1),
(583277, 60515, 5391, '<td valign="top">Very nice capture - perfect exposure, composition couldn''t be better.  I like the way the background is light, really bringing your attention to the bird.  7</td>', 'Very nice capture - perfect exposure, composition couldn''t be better.  I like the way the background is light, really bringing your attention to the bird.  7', '2004-02-17 11:31:46.000000', NULL, 1),
(583278, 60398, 14453, '<td valign="top">It''s the first time in my life that I see a black swan... Surprising!</td>', 'It''s the first time in my life that I see a black swan... Surprising!', '2004-02-17 11:31:47.000000', NULL, 1),
