(584141, 60398, 4767, '<td valign="top">Not your basic pose for a swan.  I like it though!  One gets sick of that S-curve most swan pics show...</td>', 'Not your basic pose for a swan.  I like it though!  One gets sick of that S-curve most swan pics show...', '2004-02-18 00:31:09.000000', NULL, 1),
(584152, 60511, 4767, '<td valign="top">Great concept!  Think how much higher most votes would be if it had been BLACK pumps and BLACK lingerie!</td>', 'Great concept!  Think how much higher most votes would be if it had been BLACK pumps and BLACK lingerie!', '2004-02-18 00:34:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(584156, 60660, 4767, '<td valign="top">LOL!  Subtle, but... subtle!</td>', 'LOL!  Subtle, but... subtle!', '2004-02-18 00:35:17.000000', NULL, 1),
(584248, 60685, 12253, '<td valign="top">I like this a lot, but wish the flower weren''t so oversaturated.</td>', 'I like this a lot, but wish the flower weren''t so oversaturated.', '2004-02-18 00:58:14.000000', NULL, 1),
(584498, 60202, 9906, '<td valign="top">Very nice.  I love how you have just enough detail especially around the nose!  I just wish the eyes were a little more even.  Very nice capture.  Too bad about all the comments about it being too dark...<br/>TC</td>', 'Very nice.  I love how you have just enough detail especially around the nose!  I just wish the eyes were a little more even.  Very nice capture.  Too bad about all the comments about it being too dark...TC', '2004-02-18 02:25:20.000000', NULL, 1),
(584502, 60182, 9906, '<td valign="top">Very majestic silhouette, but with such a magnificent creature I would rather see the detail.<br/>TC</td>', 'Very majestic silhouette, but with such a magnificent creature I would rather see the detail.TC', '2004-02-18 02:26:16.000000', NULL, 1),
(584507, 60398, 9906, '<td valign="top">Hmmm... a little patience and you might have been able to capture a more pleasing ''pose'' of the duck, or were you trying for black swan butt?  Otherwise nicely composed.<br/>TC</td>', 'Hmmm... a little patience and you might have been able to capture a more pleasing ''pose'' of the duck, or were you trying for black swan butt?  Otherwise nicely composed.TC', '2004-02-18 02:31:49.000000', NULL, 1),
(584508, 60687, 9906, '<td valign="top">An interesting study, but not so interesting to look at by itself.<br/>TC</td>', 'An interesting study, but not so interesting to look at by itself.TC', '2004-02-18 02:33:26.000000', NULL, 1),
(584511, 60606, 9906, '<td valign="top">This is very nice.  You managed to make black be a statement!  Wondering how many shot you had to take to get the lighting just right...<br/>TC</td>', 'This is very nice.  You managed to make black be a statement!  Wondering how many shot you had to take to get the lighting just right...TC', '2004-02-18 02:35:28.000000', NULL, 1),
(584512, 60573, 9906, '<td valign="top">IMHO in order to make this work, one tree would have to be the subject OR there would have to be more darkness.  To me this doesn''t say black, it says blue.<br/>TC</td>', 'IMHO in order to make this work, one tree would have to be the subject OR there would have to be more darkness.  To me this doesn''t say black, it says blue.TC', '2004-02-18 02:36:44.000000', NULL, 1),
(584514, 60506, 9906, '<td valign="top">Very interesting cropping here.  It looks like a comic book frame!  Very nice job of lighting to capture all the folds in the right arm.  One of the best I''ve seen so far!<br/>TC</td>', 'Very interesting cropping here.  It looks like a comic book frame!  Very nice job of lighting to capture all the folds in the right arm.  One of the best I''ve seen so far!TC', '2004-02-18 02:38:39.000000', NULL, 1),
(584517, 60414, 9906, '<td valign="top">What a difficult exposure you attempted.  You did good  on the white, but the black is a tad hard to see.<br/>TC</td>', 'What a difficult exposure you attempted.  You did good  on the white, but the black is a tad hard to see.TC', '2004-02-18 02:39:25.000000', NULL, 1),
(584521, 60097, 9906, '<td valign="top">Nice framing, but this looks too soft to be soft focus.  It just looks OOF.<br/>TC</td>', 'Nice framing, but this looks too soft to be soft focus.  It just looks OOF.TC', '2004-02-18 02:41:00.000000', NULL, 1),
(584563, 60112, 9906, '<td valign="top">I can get by with the high key treatment of black boots.  In fact this is pretty darn good job of high key black though you are blown out on the left heel.  However, the yellow border has absolutely no place here.  It is the first thing I see and the last.  Lose the yellow border, tone it down JUST a touch and you have a great shot here.<br/>TC</td>', 'I can get by with the high key treatment of black boots.  In fact this is pretty darn good job of high key black though you are blown out on the left heel.  However, the yellow border has absolutely no place here.  It is the first thing I see and the last.  Lose the yellow border, tone it down JUST a touch and you have a great shot here.TC', '2004-02-18 03:25:04.000000', NULL, 1),
(584566, 60292, 9906, '<td valign="top">Beautiful!  Love the off center, off setting reflections!<br/>TC</td>', 'Beautiful!  Love the off center, off setting reflections!TC', '2004-02-18 03:26:55.000000', NULL, 1),
(584567, 60696, 9906, '<td valign="top">Too busy, Can''t tell if it''s in focus or not (leaning toward not) and what the heck is the purple thing in the middle?  Oh and are the green things nuts?  Not sure I wanna know.<br/>TC</td>', 'Too busy, Can''t tell if it''s in focus or not (leaning toward not) and what the heck is the purple thing in the middle?  Oh and are the green things nuts?  Not sure I wanna know.TC', '2004-02-18 03:28:32.000000', NULL, 1),
(584572, 60525, 9906, '<td valign="top">Great minds think alike?   I almost did the PS2 controller.  Nice composition (a little busy maybe) and a darker background (though harder to shoot) would make for some nice shadings!<br/>TC</td>', 'Great minds think alike?   I almost did the PS2 controller.  Nice composition (a little busy maybe) and a darker background (though harder to shoot) would make for some nice shadings!TC', '2004-02-18 03:30:59.000000', NULL, 1),
(584685, 60577, 11967, '<td valign="top"><br/></td>', '', '2004-02-18 05:16:51.000000', NULL, 1),
(584852, 60673, 6008, '<td valign="top">Hrm, almost looks like lipstick. It''s an interesting idea, very abstract, slightly phallic, and I like the light on the ''metal'' rings.</td>', 'Hrm, almost looks like lipstick. It''s an interesting idea, very abstract, slightly phallic, and I like the light on the ''metal'' rings.', '2004-02-18 07:17:17.000000', NULL, 1),
(584898, 60416, 14499, '<td valign="top">Cool Idea! I have seen this sort of thing in this mandate before ;)</td>', 'Cool Idea! I have seen this sort of thing in this mandate before ;)', '2004-02-18 07:49:27.000000', NULL, 1),
(584903, 60164, 14499, '<td valign="top">dude! I want to talk to you about usin g this sucker when the voting is over. I just bought mine and I am not having much luck with it.</td>', 'dude! I want to talk to you about usin g this sucker when the voting is over. I just bought mine and I am not having much luck with it.', '2004-02-18 07:51:12.000000', NULL, 1),
(585005, 60463, 17206, '<td valign="top">Love the use of relective light...  How long did it take to shine up these helmet?</td>', 'Love the use of relective light...  How long did it take to shine up these helmet?', '2004-02-18 09:02:34.000000', NULL, 1),
(585094, 60097, 8367, '<td valign="top">I like the lighting effect you captured in the coffee and the cup on the edge. I would prefer it to be sharper, though.</td>', 'I like the lighting effect you captured in the coffee and the cup on the edge. I would prefer it to be sharper, though.', '2004-02-18 09:47:00.000000', NULL, 1),
(585133, 60511, 8367, '<td valign="top">I tried to do this same shot and gave up. You''ve captured it very well with great detail. Where''s the black, though?</td>', 'I tried to do this same shot and gave up. You''ve captured it very well with great detail. Where''s the black, though?', '2004-02-18 09:59:52.000000', NULL, 1),
(585134, 60665, 6130, '<td valign="top">I like it.</td>', 'I like it.', '2004-02-18 10:00:04.000000', NULL, 1),
(585136, 60469, 6130, '<td valign="top">Great.10</td>', 'Great.10', '2004-02-18 10:00:30.000000', NULL, 1),
(585471, 60159, 12253, '<td valign="top">Nice, but A bit too dark on both my monitors!  Barely perceptible person.</td>', 'Nice, but A bit too dark on both my monitors!  Barely perceptible person.', '2004-02-18 11:41:13.000000', NULL, 1),
(585548, 60153, 6008, '<td valign="top">First thing I notice is that the ''horizon'' line is tilted, not usually a good thing unless it''s an extreme angle or for a set mood. Seconly the lighting seems a little dull. The white is white, but it''s not too bright, which is what you normally see in product shots like this. What light reflections there are are placed well and not too strong. This also looks like you placed the item flat on the background as there is ''texture'' in the black nearer the top. I''m guessing you did that to reduce shadow, but sometimes shadow can be a good thing to add dimension and depth to an image.</td>', 'First thing I notice is that the ''horizon'' line is tilted, not usually a good thing unless it''s an extreme angle or for a set mood. Seconly the lighting seems a little dull. The white is white, but it''s not too bright, which is what you normally see in product shots like this. What light reflections there are are placed well and not too strong. This also looks like you placed the item flat on the background as there is ''texture'' in the black nearer the top. I''m guessing you did that to reduce shadow, but sometimes shadow can be a good thing to add dimension and depth to an image.', '2004-02-18 12:07:45.000000', NULL, 1),
(585557, 60539, 6008, '<td valign="top">The composition is good - I like the arc of the ''thing'' and also the placement of the boy. Not usually a fan of the part black and white/part color, but this works to contrast the balls against the subject. I like the lower circular light flashes, but the two near the middle that looks like a result of the camera flash are a little too ''camera flash'' looking and spoil the effect. As this was advanced editing I think if you had cloned them out it would have improved the shot greatly.</td>', 'The composition is good - I like the arc of the ''thing'' and also the placement of the boy. Not usually a fan of the part black and white/part color, but this works to contrast the balls against the subject. I like the lower circular light flashes, but the two near the middle that looks like a result of the camera flash are a little too ''camera flash'' looking and spoil the effect. As this was advanced editing I think if you had cloned them out it would have improved the shot greatly.', '2004-02-18 12:12:03.000000', NULL, 1),
(585561, 60067, 6008, '<td valign="top">Hrm, avocado? The light is good, enough to show the great texture of the fruit but not too much to completely blow it out. I also like how it fades out into pure black. The disconnected ''thing'' on the right, I assume the stem, is a little distracting simply because it''s not connected to it, but not overly so.</td>', 'Hrm, avocado? The light is good, enough to show the great texture of the fruit but not too much to completely blow it out. I also like how it fades out into pure black. The disconnected ''thing'' on the right, I assume the stem, is a little distracting simply because it''s not connected to it, but not overly so.', '2004-02-18 12:15:26.000000', NULL, 1),
(585586, 60500, 14620, '<td valign="top">Hmmmm, pushing it, pushing it,  pushing it .... If not for your title this really wouldn''t fit the challenge.  Yes, I see the black hole but to me the main subject of this picture is the lifesaver and we all know they''re not black.  Way to think out of the box though.  But technically speaking the focus is a little soft and there is a little noise in the background.  Nice Try. :)</td>', 'Hmmmm, pushing it, pushing it,  pushing it .... If not for your title this really wouldn''t fit the challenge.  Yes, I see the black hole but to me the main subject of this picture is the lifesaver and we all know they''re not black.  Way to think out of the box though.  But technically speaking the focus is a little soft and there is a little noise in the background.  Nice Try. :)', '2004-02-18 12:31:21.000000', NULL, 1),
(585611, 60688, 12902, '<td valign="top">I love this shot. I have nothing smart or helpful to say but I have to say how much I like it. 10</td>', 'I love this shot. I have nothing smart or helpful to say but I have to say how much I like it. 10', '2004-02-18 12:44:36.000000', NULL, 1),
(585614, 60212, 12902, '<td valign="top">It is you Elena? Or thre is another painter on DPC? I like the photo anyway. 10</td>', 'It is you Elena? Or thre is another painter on DPC? I like the photo anyway. 10', '2004-02-18 12:46:48.000000', NULL, 1),
(585632, 60442, 12902, '<td valign="top">Are you a Go player? If you are then you thought that nobody will know what a Ko is. I would have loved to see a photo of a real Ko. Black involves the existence of white anyway so you could take a photo of the blacks and the whites. 9 <br/> <br/> <br/> <br/></td>', 'Are you a Go player? If you are then you thought that nobody will know what a Ko is. I would have loved to see a photo of a real Ko. Black involves the existence of white anyway so you could take a photo of the blacks and the whites. 9    ', '2004-02-18 12:54:00.000000', NULL, 1),
(585663, 60392, 6008, '<td valign="top">At first I cringed at the title, but then I realised the connection/pun and found it quite humorous! Great use of dof, and the tonal range is good. There is enough light to give the metal a texture but dark enough to set a mood. Old typewriters sure seem to have a lot of character. Good shot, I like it.</td>', 'At first I cringed at the title, but then I realised the connection/pun and found it quite humorous! Great use of dof, and the tonal range is good. There is enough light to give the metal a texture but dark enough to set a mood. Old typewriters sure seem to have a lot of character. Good shot, I like it.', '2004-02-18 13:04:58.000000', NULL, 1),
(585667, 60541, 12902, '<td valign="top">Brilliant! The photo is clear and flawless the idea  is great and the way you applied is just breath taking.  I wish it ribbon. 10 from me.</td>', 'Brilliant! The photo is clear and flawless the idea  is great and the way you applied is just breath taking.  I wish it ribbon. 10 from me.', '2004-02-18 13:06:32.000000', NULL, 1),
(585677, 60469, 6008, '<td valign="top">Interesting idea and a fairly surreal, moody image. The texture of the rock and ground is good, the light is consistent and enough to show what it is but also leave some dark shadowed areas. The person adds interest, and color, and begs the question of why he is there, what does it mean etc. An original idea.</td>', 'Interesting idea and a fairly surreal, moody image. The texture of the rock and ground is good, the light is consistent and enough to show what it is but also leave some dark shadowed areas. The person adds interest, and color, and begs the question of why he is there, what does it mean etc. An original idea.', '2004-02-18 13:08:57.000000', NULL, 1),
(585686, 60258, 6008, '<td valign="top">Not sure if those specks are sand or not but I have to admit to not being much of a fan of them. The textures of the shells are good, and the lighting is low but enough to give them a mood. The top shell is a little darker than the others and has lost some of its details, but that''s just a minor nitpick.</td>', 'Not sure if those specks are sand or not but I have to admit to not being much of a fan of them. The textures of the shells are good, and the lighting is low but enough to give them a mood. The top shell is a little darker than the others and has lost some of its details, but that''s just a minor nitpick.', '2004-02-18 13:11:18.000000', NULL, 1),
(585696, 60417, 6008, '<td valign="top">The focus is good. The composition is interesting, and I can see how the light guides the eye through the components of the image. Part of me would prefer some more darker and shadowed areas, particularly in the spaces where the background material shows through. Having it slightly darker would have emphasized the light trails more.</td>', 'The focus is good. The composition is interesting, and I can see how the light guides the eye through the components of the image. Part of me would prefer some more darker and shadowed areas, particularly in the spaces where the background material shows through. Having it slightly darker would have emphasized the light trails more.', '2004-02-18 13:14:53.000000', NULL, 1),
