(591461, 60292, 12733, '<td valign="top">A pretty pot, and nicely captured.</td>', 'A pretty pot, and nicely captured.', '2004-02-20 22:59:27.000000', NULL, 1),
(591464, 60186, 6073, '<td valign="top">Spare me the flowers...............PLEASE   Good shot..but it is a flower.</td>', 'Spare me the flowers...............PLEASE   Good shot..but it is a flower.', '2004-02-20 23:00:00.000000', NULL, 1),
(591465, 60688, 12733, '<td valign="top">More like black and pink and yellow. A pretty selection of flowers, but the black becomes pretty much irrelevant as background.</td>', 'More like black and pink and yellow. A pretty selection of flowers, but the black becomes pretty much irrelevant as background.', '2004-02-20 23:00:28.000000', NULL, 1),
(591468, 60689, 11895, '<td valign="top">excellent idea, what says black better than a big ole caddy?</td>', 'excellent idea, what says black better than a big ole caddy?', '2004-02-20 23:01:53.000000', NULL, 1),
(591470, 60663, 11895, '<td valign="top">a lovely flower shot that fits the topic well</td>', 'a lovely flower shot that fits the topic well', '2004-02-20 23:02:05.000000', NULL, 1),
(591492, 60649, 6073, '<td valign="top">One of the few time I have seen Grain work.  I don''t know what this is, and I don''t care.  It''s a great photo.  What''s right = Framing &amp; composition &amp; lighting.   The edges of the two side vertical elements seem to be non-linear from compression, but that''s ok given the restraints of the challenge.  It also has a slight tilt from right to left...but I''m ok with that too.   Still a 10 in my book</td>', 'One of the few time I have seen Grain work.  I don''t know what this is, and I don''t care.  It''s a great photo.  What''s right = Framing & composition & lighting.   The edges of the two side vertical elements seem to be non-linear from compression, but that''s ok given the restraints of the challenge.  It also has a slight tilt from right to left...but I''m ok with that too.   Still a 10 in my book', '2004-02-20 23:12:06.000000', NULL, 1),
(591539, 60506, 11769, '<td valign="top">Impressive. Nice use of black and low light.</td>', 'Impressive. Nice use of black and low light.', '2004-02-20 23:32:37.000000', NULL, 1),
